const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const gobiDesert = ee.Geometry.Rectangle([95, 40, 115, 45]); // Bounding box for the Gobi Desert
  const date2019 = ee.Filter.date('2019-02-01', '2019-03-01');
  const date2020 = ee.Filter.date('2020-02-01', '2020-03-01');

  // 2. Data Acquisition
  const collectionId = 'MODIS/061/MCD19A2_GRANULES';
  const band = 'Optical_Depth_055'; // AOD at 550nm, scale factor 0.001

  const col2019 = ee.ImageCollection(collectionId)
      .filterBounds(gobiDesert)
      .filter(date2019)
      .select(band);

  const col2020 = ee.ImageCollection(collectionId)
      .filterBounds(gobiDesert)
      .filter(date2020)
      .select(band);

  // 3. Pre-computation Checks
  const size2019 = col2019.size().getInfo();
  const size2020 = col2020.size().getInfo();

  if (size2019 === 0 || size2020 === 0) {
    console.log(`Image count 2019: ${size2019}`);
    console.log(`Image count 2020: ${size2020}`);
    console.log("No images found for one or both periods.");
    console.log("A"); // C1
    return;
  }

  // 4. Processing & Calculation
  // Create mean composites for each period.
  // The data has a valid range of -100 to 5000. Masking values outside this range.
  const image2019 = col2019.mean().updateMask(ee.Image().select(band).gte(-100).and(ee.Image().select(band).lte(5000)));
  const image2020 = col2020.mean().updateMask(ee.Image().select(band).gte(-100).and(ee.Image().select(band).lte(5000)));

  const scale = 3000; // Use a coarse scale to avoid timeout.

  // Define reducer for mean and count
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2019 = image2019.reduceRegion({
    reducer: reducer,
    geometry: gobiDesert,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = image2020.reduceRegion({
    reducer: reducer,
    geometry: gobiDesert,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  // 5. Validation & Final Answer
  const aod2019 = stats2019[band + '_mean'];
  const pixels2019 = stats2019[band + '_count'];

  const aod2020 = stats2020[band + '_mean'];
  const pixels2020 = stats2020[band + '_count'];

  console.log(`Image granules found for 2019: ${size2019}`);
  console.log(`Image granules found for 2020: ${size2020}`);

  if (pixels2019 === 0 || pixels2020 === 0) {
      console.log(`Valid pixels 2019: ${pixels2019}`);
      console.log(`Valid pixels 2020: ${pixels2020}`);
      console.log("No valid pixels after processing for one or both periods.");
      console.log("A"); // C2
      return;
  }

  // Apply scale factor
  const scaledAod2019 = aod2019 * 0.001;
  const scaledAod2020 = aod2020 * 0.001;

  if (aod2019 === null || aod2020 === null) {
      console.log("Failed to calculate a valid AOD value.");
      console.log("A"); // C3
      return;
  }

  console.log(`Feb 2019 Mean AOD: ${scaledAod2019.toFixed(3)} (from ${pixels2019} pixels)`);
  console.log(`Feb 2020 Mean AOD: ${scaledAod2020.toFixed(3)} (from ${pixels2020} pixels)`);

  if (scaledAod2020 > scaledAod2019) {
    console.log("A"); // A
  } else {
    console.log("B"); // B
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D"); // D
});
